  "b9c7944d6b198f4515950e10d2c0e6c1895f8810aa722d588cfdb3365a1397e7": async (vscode, targetPath, needles) => {
    const document = await vscode.workspace.openTextDocument(vscode.Uri.file(targetPath));
    const source = document.getText();
    const position = (needle, occurrence = 0, offset = 1) => {
      let index = -1;
      for (let count = 0; count <= occurrence; count++) {
        index = source.indexOf(needle, index + 1);
      }
      if (index < 0) {
        throw new Error(`Missing ${needle} occurrence ${occurrence} in ${targetPath}`);
      }
      return document.positionAt(index + offset);
    };
    const references = await vscode.commands.executeCommand('vscode.executeReferenceProvider', document.uri, position(needles.declaration));
    const highlights = await vscode.commands.executeCommand('vscode.executeDocumentHighlights', document.uri, position('literalColor', 1));
    const renameEdit = await vscode.commands.executeCommand('vscode.executeDocumentRenameProvider', document.uri, position('uv = pixelPosition'), 'screenUv');
    const describeEdit = edit => (edit?.entries() ?? []).map(([uri, edits]) => ({
      path: uri.fsPath,
      edits: edits.map(item => ({
        line: item.range.start.line,
        newText: item.newText
      }))
    }));
    let includedRename;
    try {
      includedRename = describeEdit(await vscode.commands.executeCommand('vscode.executeDocumentRenameProvider', document.uri, position('twice(value)'), 'doubled'));
    } catch (error) {
      // VS Code surfaces a declined rename as a thrown error.
      includedRename = {
        declined: String(error)
      };
    }
    return {
      references: (references ?? []).map(item => ({
        path: item.uri.fsPath,
        line: item.range.start.line
      })),
      highlights: (highlights ?? []).map(item => ({
        line: item.range.start.line,
        kind: item.kind
      })),
      rename: describeEdit(renameEdit),
      includedRename
    };
  },
